def f(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    lr=[r for r in range(H) if g[r] and all(x==2 for x in g[r])][0]
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]==4]
    above=[(r,c) for r,c in pts if r<lr]
    if above:
        r0,c0=min(above,key=lambda p:lr-p[0])
        ar,ac=r0+1,c0
        for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
            r,c=ar,ac
            while 0<=r<H and 0<=c<W and r!=lr:
                out[r][c]=4; r+=dr; c+=dc
        for r,c in above:
            out[r][c]=0
            if (r,c)!=(r0,c0): out[r+1][c]=4
    for r,c in pts:
        if r>lr: out[r][c]=0; out[r+1][c]=4
    return out
